#include <zephyr/kernel.h>
#include <zephyr/devicetree.h>
#include <zephyr/drivers/adc.h>

/* Get the ADC device tree spec for the node alias "zephyr_user" */
static const struct adc_dt_spec adc_spec = ADC_DT_SPEC_GET(DT_PATH(zephyr_user));

int main(void)
{
    int ret;
    int16_t buf;          /* buffer for the raw ADC sample */

    /* Ensure the ADC device is ready */
    if (!device_is_ready(adc_spec.dev)) {
        printk("ADC device not ready\n");
        return 1;
    }

    /* Configure the ADC channel */
    ret = adc_channel_setup_dt(&adc_spec);
    if (ret < 0) {
        printk("adc_channel_setup_dt() failed (%d)\n", ret);
        return 1;
    }

    /* Prepare the ADC sequence */
    const struct adc_sequence seq = {
        .channels = BIT(adc_spec.channel),
        .buffer   = &buf,
        .buffer_size = sizeof(buf),
        .resolution = adc_spec.resolution,
        .oversample = 0,
        .calibrate  = 0,
        .options    = NULL,
        .flags      = 0,
    };

    while (1) {
